def dedupe_audit_reports(apps, schema_editor):
    """Keep the newest report per (audit, agent) before enforcing uniqueness."""

    AuditReport = apps.get_model("audits", "AuditReport")
    duplicates = (
        AuditReport.objects.values("audit_id", "agent_id")
        .annotate(report_count=Count("id"))
        .filter(report_count__gt=1)
    )
    for duplicate in duplicates:
        rows = AuditReport.objects.filter(
            audit_id=duplicate["audit_id"], agent_id=duplicate["agent_id"]
        ).order_by("-created_at", "-id")
        keeper = rows.first()
        if keeper is not None:
            rows.exclude(pk=keeper.pk).delete()


